contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address other) public payable {
        require(other != address(0) && other != address(this));

        uint256 beforeOther = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 beforeThis = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 beforeContractBalance = address(c).balance;

        bool reverted;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint256 afterOther = c.balances(other); if (__ESBMC_reverted()) return;
        uint256 afterThis = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint256 afterContractBalance = address(c).balance;

        if (reverted) {
            assert(afterThis == beforeThis);
            assert(afterContractBalance == beforeContractBalance);
        } else {
            assert(afterThis == 0);
            assert(afterContractBalance == beforeContractBalance - beforeThis);
        }

        assert(afterOther == beforeOther);
    }

    receive() external payable {}
}

